css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .58); position: relative; }
.loader i { position: absolute; height: 3%; border-radius: 2px; background: color-mix(in srgb, var(--accent) 35%, transparent); transform-origin: 0 50%; }
.loader i:nth-of-type(1) { left: 12%; top: 68%; width: 34%; transform: rotate(-52deg); }
.loader i:nth-of-type(2) { left: 36%; top: 22%; width: 34%; transform: rotate(52deg); }
.loader i:nth-of-type(3) { left: 60%; top: 70%; width: 34%; transform: rotate(-52deg); }
.loader span { position: absolute; width: 13%; height: 13%; border-radius: 50%; background: color-mix(in srgb, var(--accent) 55%, transparent); box-shadow: inset 0 0 0 2px var(--accent); animation: hop-node calc(var(--loader-speed) * 2.8) ease-out infinite; }
.loader span:nth-of-type(1) { left: 6%; top: 62%; }
.loader span:nth-of-type(2) { left: 32%; top: 16%; animation-delay: calc(var(--loader-speed) * .7); }
.loader span:nth-of-type(3) { left: 56%; top: 64%; animation-delay: calc(var(--loader-speed) * 1.4); }
.loader span:nth-of-type(4) { left: 82%; top: 18%; animation-delay: calc(var(--loader-speed) * 2.1); }
.loader .packet { position: absolute; width: 8%; height: 8%; border-radius: 2px; background: var(--accent-2); box-shadow: 0 0 10px var(--accent-2); animation: hop-route calc(var(--loader-speed) * 2.8) cubic-bezier(.5, 0, .4, 1) infinite; }
@keyframes hop-route { 0% { left: 8.5%; top: 64.5%; opacity: 0; } 6% { opacity: 1; } 25% { left: 34.5%; top: 18.5%; } 50% { left: 58.5%; top: 66.5%; } 75%, 90% { left: 84.5%; top: 20.5%; opacity: 1; } 100% { left: 84.5%; top: 20.5%; opacity: 0; } }
@keyframes hop-node { 0%, 18% { transform: scale(1); background: color-mix(in srgb, var(--accent) 55%, transparent); } 25% { transform: scale(1.35); background: var(--accent-2); } 45%, 100% { transform: scale(1); background: color-mix(in srgb, var(--accent) 55%, transparent); } }
